# Adds 20-per-page pagination and a CSV download/export button
# to the newsletter subscribers admin page.
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\admin\subscribers\page.tsx"), $bytes)
Write-Host "UPDATED: src\app\admin\subscribers\page.tsx" -ForegroundColor Green
Write-Host "Now run: npx tsc --noEmit" -ForegroundColor Cyan